package calc

// Add returns the sum of a and b.
func Add(a, b int) int {
	return a + b
}

package calc

// Max returns the larger of a and b.
func Max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

package calc

import "testing"

func TestIsEven(t *testing.T) {
	tests := []struct {
		n    int
		want bool
	}{
		{0, true},
		{1, false},
		{2, true},
		{-3, false},
		{-4, true},
	}
	for _, tc := range tests {
		if got := IsEven(tc.n); got != tc.want {
			t.Errorf("IsEven(%d) = %v, want %v", tc.n, got, tc.want)
		}
	}
}

package calc

// IsEven returns true if n is even, false otherwise.
func IsEven(n int) bool {
	return n%2 == 0
}

package calc

import "testing"

func TestMax(t *testing.T) {
	tests := []struct {
		a, b, want int
	}{
		{1, 2, 2},
		{3, 0, 3},
		{-1, -2, -1},
		{5, 5, 5},
		{0, 0, 0},
	}
	for _, tc := range tests {
		got := Max(tc.a, tc.b)
		if got != tc.want {
			t.Errorf("Max(%d, %d) = %d, want %d", tc.a, tc.b, got, tc.want)
		}
	}
}

package calc

// Reverse returns the reversed form of s.
func Reverse(s string) string {
	r := []rune(s)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i]
	}
	return string(r)
}

package calc

import "testing"

func TestReverse(t *testing.T) {
	tests := []struct {
		input, want string
	}{
		{"hello", "olleh"},
		{"", ""},
		{"a", "a"},
		{"world", "dlrow"},
		{"ab", "ba"},
	}
	for _, tc := range tests {
		got := Reverse(tc.input)
		if got != tc.want {
			t.Errorf("Reverse(%q) = %q, want %q", tc.input, got, tc.want)
		}
	}
}
